'use client';

import * as React from 'react';
import {createComponent, type EventName} from '@lit/react';
import '@material/web/labs/gb/components/checkbox/md-gb-checkbox.js';
import {CheckboxElement} from '@material/web/labs/gb/components/checkbox/checkbox-element.js';

/**
 * A Material Design component. Wraps <md-gb-checkbox>.
 * Docs: https://material-web.dev/3.0/components/checkbox/
 */
export const MdCheckbox = createComponent({
  react: React,
  tagName: 'md-gb-checkbox',
  elementClass: CheckboxElement,
  events: {
    onChange: 'change' as EventName<Event>,
    onInput: 'input' as EventName<InputEvent>,
  },
});

export type MdCheckboxProps = React.ComponentProps<typeof MdCheckbox>;
